export function localizeKnownLocation(name: string, language: string): string {
  const locale = language.toLowerCase().split('-')[0] as Locale;
  if (locale !== 'en' && localizedStateNames[locale]?.[name.trim()]) return localizedStateNames[locale][name.trim()];
  const key = locationTermKeys[name.trim().toLowerCase()];
  if (key) return translate(language, key);
  const state = stateByCanonicalName(name);
  if (state) return geographicDisplayName(state, language);
  const normalized = name.trim().toLocaleLowerCase('en');
  const district = indianGeography.flatMap((item) => item.districts).find((item) => item.name.toLocaleLowerCase('en') === normalized);
  return district ? geographicDisplayName(district, language) : name;
}
