// Several components consume `messages[locale]` directly. Keep that public
// dictionary in sync with late-added translations so those screens cannot
// silently bypass the supplemental catalog.
for (const locale of Object.keys(supplemental) as Array<Exclude<Locale, 'en'>>) {
  Object.assign(messages[locale], supplemental[locale] ?? {});
}

export function translate(language: string, key: keyof typeof en): string {
  const locale = language.toLowerCase().split('-')[0] as Locale;
  return supplemental[locale]?.[key] ?? messages[locale]?.[key] ?? messages.en[key];
}

/** Return a safe display string without mutating the provider response or its metadata. */
export function assistantResponseForLanguage(response: string, responseLanguage: string | null | undefined, selectedLanguage: string): string {
  const reported = (responseLanguage ?? '').toLowerCase().split('-')[0];
  const selected = selectedLanguage.toLowerCase().split('-')[0];
  return reported && reported !== selected ? translate(selectedLanguage, 'responseLanguageUnavailable') : response;
}

/**
 * Reports strings that still resolve to English so the UI never has to claim
 * full localization just because every locale object inherits the English base.
 * This covers this catalog only; hardcoded component copy is audited separately.
 */
export function getLocalizationAudit(language: string) {
  const locale = language.toLowerCase().split('-')[0] as Locale;
  const dictionary = messages[locale];
  if (!dictionary) {
    return { language, supported: false, total: Object.keys(en).length, translated: 0,
      percentage: 0, intentionalUnchangedKeys: [] as Array<keyof typeof en>, untranslatedKeys: Object.keys(en) as Array<keyof typeof en> };
  }
  const intentionalUnchangedKeys = (locale === 'en' ? [] : ['appName']) as Array<keyof typeof en>;
  const untranslatedKeys = (Object.keys(en) as Array<keyof typeof en>).filter((key) =>
    locale !== 'en' && !intentionalUnchangedKeys.includes(key) && (supplemental[locale]?.[key] ?? dictionary[key]) === en[key]
  );
  const total = Object.keys(en).length - intentionalUnchangedKeys.length;
  return { language: locale, supported: true, total, translated: total - untranslatedKeys.length,
    percentage: Math.round(((total - untranslatedKeys.length) / total) * 100), intentionalUnchangedKeys, untranslatedKeys };
}

